<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/Members/PeopleMemberFinalizationService.php';
require_once dirname(__DIR__).'/app/Members/MemberProfileService.php';
function runFinalizationCases(PDO $db,callable $q,callable $reset,callable $pair,callable $hash,array $users):void
{
 $actor=$users['admin'];$service=new PeopleMemberFinalizationService($db);$review=new GroupedMatchReviewService($db);$bulk=new BulkExactMatchService($db,BulkExactMatchService::SCORE);
 $approve=function(array $over=[])use($pair,$bulk,$actor){$x=$pair($over);$p=$bulk->preview($actor);$bulk->confirm($actor,bin2hex(random_bytes(16)),$p['digest']);return $x;};
 $choice=static fn(int $person,string $kind,string $evidence,bool $established=true)=>[$person=>['kind'=>$kind,'evidence'=>$evidence,'established'=>$established]];
 $reset();$a=$approve();$before=$hash();$p=$service->preview($actor);$person=(int)$q('SELECT student_person_id FROM cognito_waivers')->fetchColumn();
 bulkCheck($before===$hash()&&$p['summary']['people_to_create']===0&&$p['summary']['people_to_reuse']===1&&$p['summary']['approved_groups_awaiting_finalization']===1,'read-only finalization reuses the one already approved person rather than reallocating IDs');
 bulkCheck((int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===0&&$p['summary']['membership_needs_review']===1,'adult Self waiver and financial account do not independently establish membership');
 $choices=$choice($person,'active','Administrator verified academy enrollment against the roster');$p=$service->preview($actor,$choices);bulkCheck($p['summary']['members_to_create']===1&&$p['summary']['relationships_to_establish']===0&&$p['errors']===[],'membership preview lists exactly one supported insert and no invented identity or relationship writes');
 $op=bin2hex(random_bytes(16));$service->confirm($actor,$op,$p['digest'],$choices);$before=$hash();$service->confirm($actor,$op,$p['digest'],$choices);bulkCheck($before===$hash()&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===1,'repeated finalization POST uses its receipt without duplicate member or audit records');
 $member=$q('SELECT * FROM members')->fetch();bulkCheck($member['member_status']==='active'&&$member['member_since']===null&&$member['member_until']===null,'explicit active membership does not fabricate membership dates');
 $again=$service->preview($actor,$choices);bulkCheck($again['changes']===[]&&$again['summary']['skipped']===1,'same evidence and outcome in a new preview are skipped idempotently');
 $q('UPDATE members SET member_since=? WHERE person_id=?',['2021-06-01',$person]);$choices=$choice($person,'former','Administrator verified former membership');$p=$service->preview($actor,$choices);$service->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$choices);bulkCheck($q('SELECT member_since FROM members')->fetchColumn()==='2021-06-01'&&$q('SELECT member_status FROM members')->fetchColumn()==='former','reviewed status changes retain known dates and member ID');
 $reset();$a=$approve();$person=(int)$q('SELECT student_person_id FROM cognito_waivers')->fetchColumn();$q('UPDATE cognito_waivers SET submitted_at=?,source_timezone=?',['2011-01-01 00:00:00','UTC']);$choices=$choice($person,'trial_participant','Trial attendance only, no membership established',false);$p=$service->preview($actor,$choices);$service->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$choices);$p=$service->preview($actor);
 bulkCheck((int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===0&&$p['summary']['trial_or_waiver_only']===1,'historical waiver and verified trial attendance remain people without fabricated active membership');
 $choices=$choice($person,'waiver_only','Waiver submitted; enrollment was not established',false);$p=$service->preview($actor,$choices);$service->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$choices);bulkCheck((int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===0,'waiver-only review is audited without creating a member');
 $choices=$choice($person,'trial','Administrator verified an actual trial enrollment relationship');$p=$service->preview($actor,$choices);$service->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$choices);bulkCheck($q('SELECT member_status FROM members')->fetchColumn()==='trial'&&$q('SELECT member_since FROM members')->fetchColumn()===null,'established trial enrollment is explicitly trial rather than automatically active');
 $reset();$a=$pair(['payer'=>'Megan Brown','signer'=>'Megan Brown','student'=>'Abel Hill','relationship'=>'Mother','dob'=>'2015-01-01']);$b=$pair(['payer'=>'Megan Brown','signer'=>'Megan Brown','student'=>'Ada Hill','relationship'=>'Mother','dob'=>'2014-01-01']);
 foreach(['Abel Hill','Ada Hill'] as $name){$rows=$review->queue($actor)['groups'];$g=array_values(array_filter($rows,static fn($g)=>$g['name']===$name))[0];$input=['student_verified'=>'1','signer_is_payer'=>'1','confirm_source_relationship'=>'1'];$p=$review->preview($actor,$g['id'],'manual_relationship',$input);bulkCheck($p['blockers']===[]&&$p['members_to_create']===0,'verified child identity can be approved separately from membership: '.$name);$review->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$g['id'],'manual_relationship',null,$input);}
 bulkCheck((int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===3&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===0&&(int)$q("SELECT COUNT(*) FROM person_relationships WHERE relationship_type='payer'")->fetchColumn()===2,'multiple child/account approvals reuse one mother and preserve two distinct student identities');
 $children=$q('SELECT DISTINCT student_person_id FROM cognito_waivers ORDER BY student_person_id')->fetchAll(PDO::FETCH_COLUMN);$choices=$choice((int)$children[0],'active','Verified enrollment for this child only');$p=$service->preview($actor,$choices);$service->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$choices);
 $payer=(int)$q('SELECT person_id FROM stripe_customers LIMIT 1')->fetchColumn();$q('INSERT INTO stripe_transactions(stripe_charge_id,customer_id,amount_minor,currency,status,stripe_created_at) VALUES (?,?,?,?,?,?)',['ch_FinalizationFixture',$a['cid'],13000,'usd','succeeded','2026-01-01 12:00:00']);$mid=(int)$q('SELECT id FROM members')->fetchColumn();$profile=(new MemberProfileService(new MemberProfileRepository($db)))->profile(new MemberProfileIdentifier($mid,null),'usd',true);
 bulkCheck($profile!==null&&!$profile['exclusive']&&(int)$profile['payers'][0]['related_student_count']===2,'member profile does not assign all parent payments to one child while a sibling has no member record');
 bulkCheck(count($profile['guardians'])===1&&$profile['programs']===[]&&$profile['member']['member_since']===null&&count($profile['waivers'])===1,'profile retains verified guardian and waiver history while unknown programs/start dates remain unresolved');
 $rows=$profile['totals'];bulkCheck(count($rows)===1&&(int)$rows[0]['payment_count']===1,'related payer ledger retains transaction grain without multiplying payments by relationships');$q('DELETE FROM stripe_transactions');
 $choices=$choice($payer,'active','A parent payer is not a verified student');bulkCheck($service->preview($actor,$choices)['errors']!==[],'payer and signer roles cannot be finalized as members without approved student identity');
 $reset();$approve(['payer'=>'John A. Smith','signer'=>'John Smith','student'=>'John Smith']);$approve(['payer'=>'Johnny Smith','signer'=>'John Smith','student'=>'John Smith']);bulkCheck((int)$q('SELECT COUNT(*) FROM people')->fetchColumn()===1&&(int)$q('SELECT COUNT(*) FROM stripe_customers')->fetchColumn()===2&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===0,'approved middle-initial/nickname waivers and duplicate accounts reuse one person without inferring membership');
 $reset();$a=$approve();$b=$approve(['payer'=>'Jane Jones','signer'=>'Jane Jones','student'=>'Jane Jones','payer_email'=>'jane@example.invalid','waiver_email'=>'jane@example.invalid']);$choices=[];foreach($q('SELECT DISTINCT student_person_id FROM cognito_waivers')->fetchAll(PDO::FETCH_COLUMN) as $id)$choices+=$choice((int)$id,'active','Verified separate enrollment');$p=$service->preview($actor,$choices);$before=$hash();$db->armMembership(2);bulkThrows(fn()=>$service->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$choices),'SYNTHETIC_MEMBERSHIP_FAILURE','second member failure aborts the complete operation');$db->armMembership(0);bulkCheck($before===$hash(),'rollback restores member rows and all audits without altering approved source associations');
 $q("UPDATE identity_match_candidates SET match_reason='manual_review_pending',reviewed_by=?,reviewed_at=UTC_TIMESTAMP(6) WHERE id=?",[$actor,$b['ids']['source_name_unresolved']]);bulkThrows(fn()=>$service->confirm($actor,bin2hex(random_bytes(16)),$p['digest'],$choices),'FINALIZATION_STALE','a new manual hold makes an earlier finalization preview stale');$p=$service->preview($actor,$choices);bulkCheck($p['errors']!==[],'held/conflicting identity groups remain excluded from finalization');
 bulkThrows(fn()=>$service->preview($users['viewer']),'ADMIN_REVIEW_REQUIRED','viewer cannot access finalization service');bulkThrows(fn()=>PeopleMemberFinalizationService::choices([1=>['include'=>'1','kind'=>'active','evidence'=>'Waiver only']]),'MEMBERSHIP_EVIDENCE_REQUIRED','active status without explicit membership evidence is rejected');
}
function runFinalizationHttpCases(PDO $db,callable $q,callable $reset,callable $pair,callable $hash,callable $http,string $cookie,array $users):void
{
 $reset();$pair();$bulk=new BulkExactMatchService($db,BulkExactMatchService::SCORE);$p=$bulk->preview($users['admin']);$bulk->confirm($users['admin'],bin2hex(random_bytes(16)),$p['digest']);$pid=(int)$q('SELECT student_person_id FROM cognito_waivers')->fetchColumn();$before=$hash();[$code,$html]=$http('/admin/finalize-members.php',$cookie);bulkCheck($code===200&&str_contains($html,'Finalize People &amp; Members')&&$before===$hash(),'authenticated finalization GET is read-only and lists approved people');preg_match('/name="csrf" value="([a-f0-9]+)"/',$html,$csrf);
 [$code]=$http('/admin/finalize-members.php',$cookie,['csrf'=>'bad','phase'=>'preview']);bulkCheck($code===403&&$before===$hash(),'invalid CSRF cannot prepare or apply finalization');
 $post=['csrf'=>$csrf[1],'phase'=>'preview','people'=>[$pid=>['include'=>'1','kind'=>'active','established'=>'1','evidence'=>'Verified academy roster']]];[$code,$html]=$http('/admin/finalize-members.php',$cookie,$post);bulkCheck($code===200&&str_contains($html,'Confirm Reviewed Finalization')&&$before===$hash(),'membership selection prepares a precise preview without database writes');preg_match('/name="operation_id" value="([a-f0-9]+)"/',$html,$op);$post=['csrf'=>$csrf[1],'operation_id'=>$op[1],'confirm_count'=>'1','acknowledge'=>'1'];[$code]=$http('/admin/finalize-members.php',$cookie,$post);bulkCheck($code===303&&(int)$q('SELECT COUNT(*) FROM members')->fetchColumn()===1,'explicit authenticated finalization confirmation creates the supported member locally');$before=$hash();[$code]=$http('/admin/finalize-members.php',$cookie,$post);bulkCheck($code===303&&$before===$hash(),'HTTP repeat confirmation replays its receipt without duplicate writes');
 [$code]=$http('/admin/finalize-members.php');bulkCheck($code===303,'unauthenticated finalization redirects to application login');$q("UPDATE app_users SET role='viewer' WHERE id=?",[$users['admin']]);[$code]=$http('/admin/finalize-members.php',$cookie);bulkCheck($code===403,'canonical viewer role cannot access finalization directly');$q("UPDATE app_users SET role='admin' WHERE id=?",[$users['admin']]);
 $dashboard=(int)$q("SELECT id FROM dashboards WHERE dashboard_key='matches'")->fetchColumn();$q("INSERT INTO user_dashboard_overrides(user_id,dashboard_id,permission) VALUES (?,?,'DENY')",[$users['admin'],$dashboard]);[$code]=$http('/admin/finalize-members.php',$cookie);bulkCheck($code===403,'Matches dashboard denial also protects finalization');$q('DELETE FROM user_dashboard_overrides WHERE user_id=? AND dashboard_id=?',[$users['admin'],$dashboard]);
}
